{% stylesheet %}
  .popup-link__button svg {
    display: inline-block;
    position: relative;
    top: var(--margin-2xs);
  }

  .popup-link__content {
    box-shadow: var(--shadow-popover);
    border: var(--style-border-popover);
    border-radius: var(--style-border-radius-popover);
    background-color: var(--color-background);
    padding: var(--padding-4xl) var(--padding-xl) var(--padding-xl);
    max-width: var(--normal-content-width);
    max-height: var(--modal-max-height);

    @media screen and (min-width: 750px) {
      padding: var(--padding-5xl);
    }
  }

  .popup-link__content[open] {
    animation: modalSlideInTop var(--animation-speed) var(--animation-easing) forwards;
  }

  .popup-link__content.dialog-closing {
    animation: modalSlideOutTop var(--animation-speed) var(--animation-easing) forwards;
  }

  .popup-link__content--drawer {
    position: fixed;
    border-radius: 0;
    width: var(--sidebar-width);
    max-width: 95vw;
    height: 100%;
    margin: 0;
    margin-inline-start: auto;

    /* Inline-end-anchored drawer spans the full physical viewport (viewport-fit=cover); keep its
       content clear of the outer-edge notch and home indicator */
    padding-inline-end: calc(var(--padding-xl) + var(--safe-area-inset-right));
    padding-block-end: calc(var(--padding-xl) + var(--safe-area-inset-bottom));

    @media screen and (min-width: 750px) {
      padding-inline-end: calc(var(--padding-5xl) + var(--safe-area-inset-right));
      padding-block-end: calc(var(--padding-5xl) + var(--safe-area-inset-bottom));
    }
  }

  /* Safe-area env() values are physical; the mirrored drawer's outer edge is the left notch in RTL */
  [dir='rtl'] .popup-link__content--drawer {
    padding-inline-end: calc(var(--padding-xl) + var(--safe-area-inset-left));

    @media screen and (min-width: 750px) {
      padding-inline-end: calc(var(--padding-5xl) + var(--safe-area-inset-left));
    }
  }

  /* The drawer slides in from its anchored edge; mirror the animation in RTL */
  [dir='rtl'] .popup-link__content--drawer[open] {
    --start-x: -100%;
  }

  [dir='rtl'] .popup-link__content--drawer[open].dialog-closing {
    --end-x: -100%;
  }

  /* Needed to ensure the drawer is full height */
  .popup-link__content--drawer:modal {
    max-height: 100dvh;
  }

  .popup-link__close {
    top: var(--margin-2xs);
    inset-inline-end: var(--margin-2xs);
    opacity: 0.8;
    animation: none;
  }

  /* Match the specificity of the base [dir='rtl'] .close-button safe-area rule so
     the popup close button keeps its own corner inset in RTL */
  [dir='rtl'] .popup-link__close {
    inset-inline-end: var(--margin-2xs);
  }

  /* The close button is absolutely positioned so it bypasses the drawer's safe-area padding */
  .popup-link__content--drawer .popup-link__close {
    top: max(var(--margin-2xs), var(--safe-area-inset-top));
    inset-inline-end: max(var(--margin-2xs), var(--safe-area-inset-right));
  }

  /* Safe-area env() values are physical; in RTL the button sits by the left-side notch */
  [dir='rtl'] .popup-link__content--drawer .popup-link__close {
    inset-inline-end: max(var(--margin-2xs), var(--safe-area-inset-left));
  }
{% endstylesheet %}

